def transform(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda v: counts[v])
    non_bg = [v for v in counts if v != bg]
    if not non_bg:
        return [row[:] for row in grid]
    fg = max(non_bg, key=lambda v: counts[v])
    coords = [(r, c) for r, row in enumerate(grid)
              for c, v in enumerate(row) if v == fg]
    if not coords:
        return [row[:] for row in grid]
    r0 = min(r for r, c in coords); r1 = max(r for r, c in coords)
    c0 = min(c for r, c in coords); c1 = max(c for r, c in coords)
    fill = 2 if bg != 2 else 0
    out = [row[:] for row in grid]

    def put(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == bg:
            out[r][c] = fill

    # fill all bg cells on the bounding-box border
    for c in range(c0, c1 + 1):
        put(r0, c); put(r1, c)
    for r in range(r0, r1 + 1):
        put(r, c0); put(r, c1)

    # fill single bg cells between two shape cells in a row
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == bg and grid[r][c - 1] == fg and grid[r][c + 1] == fg:
                put(r, c)
    # ... and in a column
    for c in range(w):
        for r in range(1, h - 1):
            if grid[r][c] == bg and grid[r - 1][c] == fg and grid[r + 1][c] == fg:
                put(r, c)
    return out
